const F = {"/knowledge/sti-hiv/do-i-need-pep-or-prep/": ["text/html; charset=utf-8", ""], "/en/knowledge/sti-hiv/do-i-need-pep-or-prep/": ["text/html; charset=utf-8", ""], "/knowledge/sti-hiv/hiv-risk-assessment/": ["text/html; charset=utf-8", ""], "/en/knowledge/sti-hiv/hiv-risk-assessment/": ["text/html; charset=utf-8", ""], "/knowledge/sti-hiv/do-i-need-pep-or-prep/img/pep-prep-consult.webp": ["image/webp", ""], "/knowledge/sti-hiv/do-i-need-pep-or-prep/img/prep-umbrella.webp": ["image/webp", ""], "/knowledge/sti-hiv/do-i-need-pep-or-prep/img/og-do-i-need-pep-or-prep.jpg": ["image/jpeg", ""], "/knowledge/sti-hiv/hiv-risk-assessment/img/hiv-risk-scale.webp": ["image/webp", ""], "/knowledge/sti-hiv/hiv-risk-assessment/img/hiv-risk-shield.webp": ["image/webp", ""], "/knowledge/sti-hiv/hiv-risk-assessment/img/og-hiv-risk-assessment.jpg": ["image/jpeg", ""]};
function b64(s){const b=atob(s);const u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u;}
export default {
  async fetch(req){
    const url=new URL(req.url);let p=url.pathname;
    if(!p.endsWith('/') && !p.includes('.') ){url.pathname=p+'/';return Response.redirect(url.toString(),301);}
    const f=F[p];
    if(!f) return fetch(req);
    const [ct,data]=f;
    const h={'content-type':ct,'cache-control':ct.startsWith('image')?'public, max-age=31536000, immutable':'public, max-age=300','x-content-type-options':'nosniff'};
    return new Response(b64(data),{headers:h});
  }
};
